#requires -Version 5.1
[CmdletBinding()]
param(
    [string]$Destino = (Join-Path ([Environment]::GetFolderPath('Desktop')) 'MercadoBot-Personal-Web'),
    [string]$NombreRepositorio = 'MercadoBot-Personal-Web'
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

function Paso([string]$Texto) { Write-Host "`n==> $Texto" -ForegroundColor Cyan }
function Actualizar-Path {
    $Rutas = @(
        'C:\Program Files\Git\cmd',
        'C:\Program Files\GitHub CLI',
        (Join-Path $env:LOCALAPPDATA 'Programs\Git\cmd')
    )
    foreach ($Ruta in $Rutas) {
        if ((Test-Path $Ruta) -and ($env:Path -notlike "*$Ruta*")) { $env:Path += ";$Ruta" }
    }
}
function Instalar-Con-Winget([string]$Id, [string]$Nombre) {
    if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
        throw "Falta $Nombre y no se encontró winget. Instálalo manualmente y vuelve a ejecutar."
    }
    Paso "Instalando $Nombre"
    & winget install --id $Id -e --source winget --accept-package-agreements --accept-source-agreements
    if ($LASTEXITCODE -ne 0) { throw "No se pudo instalar $Nombre." }
    Actualizar-Path
}

Write-Host 'MERCADOBOT PERSONAL WEB v0.2.0' -ForegroundColor Green
Write-Host 'Modo: GitHub Actions + GitHub Pages; funciona con la PC apagada.' -ForegroundColor Yellow
Write-Host 'No ejecuta operaciones reales ni garantiza movimientos.' -ForegroundColor Yellow

