'@
$ShaEsperado = 'C41011E957E19D576DCDB4B85F5839651B6A6837E9B6AA0C732378FAD479784D'
$TempZip = Join-Path $env:TEMP ('MercadoBot-Web-' + [Guid]::NewGuid().ToString('N') + '.zip')

try {
    Paso 'Reconstruyendo y verificando el proyecto'
    [IO.File]::WriteAllBytes($TempZip, [Convert]::FromBase64String(($ZipBase64 -replace '\s','')))
    $ShaReal = (Get-FileHash -Algorithm SHA256 $TempZip).Hash
    if ($ShaReal -ne $ShaEsperado) { throw "Fallo de integridad SHA-256. Esperado: $ShaEsperado / Obtenido: $ShaReal" }

    if (Test-Path $Destino) {
        $Marca = Get-Date -Format 'yyyyMMdd-HHmmss'
        $Respaldo = "$Destino-RESPALDO-$Marca"
        Paso "Respaldando la carpeta anterior en $Respaldo"
        Move-Item -LiteralPath $Destino -Destination $Respaldo
    }
    New-Item -ItemType Directory -Force -Path $Destino | Out-Null
    Expand-Archive -LiteralPath $TempZip -DestinationPath $Destino -Force
    Copy-Item -LiteralPath $PSCommandPath -Destination (Join-Path $Destino 'INSTALAR-MERCADOBOT-WEB-GITHUB.ps1') -Force

    Actualizar-Path
    if (-not (Get-Command git -ErrorAction SilentlyContinue)) { Instalar-Con-Winget 'Git.Git' 'Git' }
    if (-not (Get-Command gh -ErrorAction SilentlyContinue)) { Instalar-Con-Winget 'GitHub.cli' 'GitHub CLI' }
    if (-not (Get-Command git -ErrorAction SilentlyContinue)) { throw 'Git quedó instalado, pero PowerShell no logra encontrarlo. Cierra PowerShell, ábrelo otra vez y ejecuta PUBLICAR-WEB-GITHUB.ps1 dentro de la carpeta.' }
    if (-not (Get-Command gh -ErrorAction SilentlyContinue)) { throw 'GitHub CLI quedó instalado, pero PowerShell no logra encontrarlo. Cierra PowerShell, ábrelo otra vez y ejecuta PUBLICAR-WEB-GITHUB.ps1 dentro de la carpeta.' }

    Paso 'Publicando el bot y el panel en GitHub'
    Set-Location $Destino
    & (Join-Path $Destino 'PUBLICAR-WEB-GITHUB.ps1') -NombreRepositorio $NombreRepositorio

    Write-Host "`nPROYECTO TERMINADO" -ForegroundColor Green
    Write-Host "Carpeta local: $Destino"
    Write-Host "SHA-256: $ShaEsperado" -ForegroundColor DarkGray
    Write-Host 'GitHub realizará las exploraciones aunque apagues tu computadora.' -ForegroundColor Green
    Start-Process explorer.exe $Destino
} finally {
    if (Test-Path $TempZip) { Remove-Item $TempZip -Force -ErrorAction SilentlyContinue }
}
